// Patches the native projects generated by `flutter create` with what the app
// needs: camera/photo permissions (Aadhaar card, face check, QR scan,
// documents), link handling, and the display name. Idempotent — safe to re-run.
//
//   flutter create --org com.pagerlook --project-name veriwork_mobile --platforms android,ios .
//   dart run tool/configure_platforms.dart
//
// ignore_for_file: avoid_print
import 'dart:io';

const appName = 'PagerLook';

void main() {
  var ok = true;
  ok &= _patchAndroidMain('android/app/src/main/AndroidManifest.xml');
  ok &= _patchAndroidDebug('android/app/src/debug/AndroidManifest.xml');
  ok &= _patchInfoPlist('ios/Runner/Info.plist');
  ok &= _patchRootGradle('android/build.gradle.kts');
  if (!ok) {
    print('\nSome files were missing. Run `flutter create --org com.pagerlook '
        '--project-name veriwork_mobile --platforms android,ios .` first.');
    exitCode = 1;
  } else {
    print('\nPlatform configuration complete.');
  }
}

bool _patchAndroidMain(String path) {
  final file = File(path);
  if (!file.existsSync()) {
    print('✗ $path not found');
    return false;
  }
  var xml = file.readAsStringSync();

  const permissions = [
    'android.permission.INTERNET',
    'android.permission.CAMERA',
  ];
  for (final p in permissions) {
    if (!xml.contains('"$p"')) {
      xml = xml.replaceFirstMapped(
        RegExp(r'<manifest[^>]*>'),
        (m) => '${m[0]}\n    <uses-permission android:name="$p" />',
      );
    }
  }

  if (!xml.contains('android.hardware.camera')) {
    xml = xml.replaceFirst(
      '<application',
      '<uses-feature android:name="android.hardware.camera" android:required="false" />\n    <application',
    );
  }

  xml = xml.replaceFirst(RegExp(r'android:label="[^"]*"'), 'android:label="$appName"');

  // Package visibility (Android 11+) for opening links, phone, email, WhatsApp.
  if (!xml.contains('<queries>')) {
    xml = xml.replaceFirst('</manifest>', '''
    <queries>
        <intent>
            <action android:name="android.intent.action.VIEW" />
            <data android:scheme="https" />
        </intent>
        <intent>
            <action android:name="android.intent.action.DIAL" />
            <data android:scheme="tel" />
        </intent>
        <intent>
            <action android:name="android.intent.action.SENDTO" />
            <data android:scheme="mailto" />
        </intent>
    </queries>
</manifest>''');
  }

  file.writeAsStringSync(xml);
  print('✓ $path');
  return true;
}

bool _patchAndroidDebug(String path) {
  final file = File(path);
  if (!file.existsSync()) {
    print('✗ $path not found');
    return false;
  }
  var xml = file.readAsStringSync();
  // Debug builds only: allow http:// to a local backend (10.0.2.2:8080).
  if (!xml.contains('usesCleartextTraffic')) {
    xml = xml.replaceFirst(
      '</manifest>',
      '    <application android:usesCleartextTraffic="true" />\n</manifest>',
    );
    file.writeAsStringSync(xml);
  }
  print('✓ $path');
  return true;
}

bool _patchInfoPlist(String path) {
  final file = File(path);
  if (!file.existsSync()) {
    print('✗ $path not found');
    return false;
  }
  var plist = file.readAsStringSync();

  const entries = {
    'NSCameraUsageDescription':
        'PagerLook uses the camera to photograph your Aadhaar card and documents, run the live face check, and scan PagerLook QR codes.',
    'NSPhotoLibraryUsageDescription':
        'PagerLook lets you choose photos of your Aadhaar card and documents to upload.',
  };
  entries.forEach((key, value) {
    if (!plist.contains('<key>$key</key>')) {
      plist = _insertBeforeLastDictClose(plist, '\t<key>$key</key>\n\t<string>$value</string>\n');
    }
  });

  if (!plist.contains('<key>LSApplicationQueriesSchemes</key>')) {
    plist = _insertBeforeLastDictClose(
      plist,
      '\t<key>LSApplicationQueriesSchemes</key>\n\t<array>\n'
      '\t\t<string>https</string>\n\t\t<string>tel</string>\n\t\t<string>mailto</string>\n'
      '\t\t<string>whatsapp</string>\n\t</array>\n',
    );
  }

  plist = plist.replaceFirstMapped(
    RegExp(r'(<key>CFBundleDisplayName</key>\s*<string>)[^<]*(</string>)'),
    (m) => '${m[1]}$appName${m[2]}',
  );

  file.writeAsStringSync(plist);
  print('✓ $path');
  return true;
}

/// Some plugins (file_picker 8) pin compileSdk 34, but current androidx /
/// flutter_plugin_android_lifecycle require 36 — force it for every plugin.
bool _patchRootGradle(String path) {
  final file = File(path);
  if (!file.existsSync()) {
    print('✗ $path not found');
    return false;
  }
  var gradle = file.readAsStringSync();
  if (!gradle.contains('compileSdk = 36')) {
    const anchor = 'subprojects {\n    project.evaluationDependsOn(":app")\n}';
    const override = '''// Some plugins (e.g. file_picker 8) pin an older compileSdk, but the current
// androidx/flutter plugin libraries require compiling against API 36+.
// Registered before evaluationDependsOn so it applies to every plugin project.
subprojects {
    afterEvaluate {
        if (plugins.hasPlugin("com.android.library")) {
            extensions.configure<com.android.build.gradle.LibraryExtension>("android") {
                compileSdk = 36
            }
        }
    }
}
''';
    if (!gradle.contains(anchor)) {
      print('✗ $path: unexpected layout, add the compileSdk override by hand (see README)');
      return false;
    }
    gradle = gradle.replaceFirst(anchor, '$override$anchor');
    file.writeAsStringSync(gradle);
  }
  print('✓ $path');
  return true;
}

String _insertBeforeLastDictClose(String plist, String snippet) {
  final index = plist.lastIndexOf('</dict>');
  if (index < 0) return plist;
  return plist.substring(0, index) + snippet + plist.substring(index);
}
